class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking Change 4: EF Core 9 uses patch (partial update) by default instead of
        // replace (full document). For sync jobs that read-then-write full documents,
        // this is usually fine, but if you need full replace semantics use:
        // context.Database.GetCosmosClient() with ReplaceItemAsync, or configure
        // .UseFullDocumentUpdates() on the context options.
        context.SaveChanges();
    }
}

